}

.dashboard__header h1 {
  margin: 0 0 4px;
  font-size: 28px;
}

.dashboard__subtitle {
  margin: 0 0 24px;
  color: var(--muted);
}

.filter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
}

.filter-form__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.filter-form__field label {
  font-size: 13px;
  color: var(--muted);
}

.filter-form__field input {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
}

.filter-form__actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-block;
  padding: 9px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: 14px;
  cursor: pointer;
  text-decoration: none;
}

.btn--primary {
  background: var(--primary);
  color: #fff;
}

.btn--primary:hover { background: var(--primary-dark); }

.btn--ghost {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}

.metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.metric-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.metric-card__label {
  font-size: 13px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.metric-card__value {
  font-size: 26px;
  font-weight: 700;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  margin-bottom: 24px;
}

.panel__title {
  margin: 0 0 16px;
  font-size: 18px;
}

.chart {
  display: flex;
  align-items: flex-end;
  gap: 16px;
  height: 240px;
  padding: 12px 4px 0;
  border-bottom: 2px solid var(--border);
}

.chart-bar {
  flex: 1 1 0;
  min-width: 40px;
  min-height: 4px;
  background: linear-gradient(180deg, var(--accent), var(--primary));
  border-radius: 6px 6px 0 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  position: relative;
  transition: opacity 0.15s ease;
}

.chart-bar:hover { opacity: 0.85; }

.chart-bar__label {
  position: absolute;
  bottom: -22px;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.chart-bar__value {
  position: absolute;
  top: -20px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.orders-table th,
.orders-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.orders-table thead th {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.orders-table__amount { text-align: right; }

.orders-table tfoot th {
  border-top: 2px solid var(--border);
  border-bottom: none;
}

.empty-state {
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: 12px;
  padding: 48px 24px;
  text-align: center;
}

.empty-state__title {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 600;
}

.empty-state__text {
  margin: 0;
  color: var(--muted);
}
"}

