            data-value="<%= @orders_count %>"><%= @orders_count %></span>
    </div>
    <div class="metric-card">
      <span class="metric-card__label">Ticket médio</span>
      <span id="metric-average" class="metric-card__value"
            data-value="<%= @average_ticket.to_f %>"><%= format_currency(@average_ticket) %></span>
