  </section>

  <% if @metrics.empty? %>
    <div id="empty-state" class="empty-state">
      <p class="empty-state__title">Nenhum pedido encontrado</p>
      <p class="empty-state__text">Não há pedidos no período selecionado. Ajuste o filtro de datas e tente novamente.</p>
    </div>
  <% else %>
    <section class="panel">
      <h2 class="panel__title">Vendas por categoria</h2>
      <div id="chart" class="chart">
        <% max_value = @by_category.values.max.to_f %>
        <% @by_category.sort_by { |_category, value| -value.to_f }.each do |category, value| %>
          <div class="chart-bar" data-category="<%= category %>" data-value="<%= value.to_f %>"
               style="height: <%= chart_bar_height(value, max_value) %>%;"
               title="<%= category %>: <%= format_currency(value) %>">
            <span class="chart-bar__label"><%= category %></span>
            <span class="chart-bar__value"><%= format_currency(value) %></span>
          </div>
        <% end %>
      </div>
    </section>

    <section class="panel">
      <h2 class="panel__title">Pedidos do período</h2>
      <table id="orders-table" class="orders-table">
        <thead>
          <tr>
            <th>Categoria</th>
            <th>Data</th>
            <th class="orders-table__amount">Valor</th>
          </tr>
        </thead>
        <tbody>
          <% @orders.each do |order| %>
            <tr data-amount="<%= order.amount.to_f %>">
              <td><%= order.category %></td>
              <td><%= order.order_date.strftime("%d/%m/%Y") %></td>
              <td class="orders-table__amount"><%= format_currency(order.amount) %></td>
            </tr>
          <% end %>
        </tbody>
        <tfoot>
          <tr>
            <th colspan="2">Total</th>
            <th class="orders-table__amount"><%= format_currency(@total_sales) %></th>
          </tr>
        </tfoot>
      </table>
    </section>
  <% end %>
</div>
"}
